var ROOM_DEVICE_IDS = {
    "c140402": {
        "WS523_A": 1,
        "WS523_B": 2,
        "WS502_A": 3,
        "WS502_B": 4
    },
    "c140405": {
        "WS523_A": 6,
        "WS523_B": 7,
        "WS502_A": 8,
        "WS502_B": 9
    },
    "c140408": {
        "WS523_A": 11,
        "WS523_B": 12,
        "WS502_A": 13,
        "WS502_B": 14
    },
    "c140409": {
        "WS523_A": 16,
        "WS523_B": 17,
        "WS502_A": 18,
        "WS502_B": 19
    }
};

