out.push({
    payload: JSON.stringify({
        method: "POST",
        url: "http://127.0.0.1:5001/api/v1/consumption",
        payload: { class_code: classCode, power_ac: data.power_ac_kw, occupancy: data.occupancy }
    }) + "\n"
